# tui/address_manager.py
# Main address manager - orchestrates domain and address management

import subprocess
from typing import Any, Optional

from bbsengine6.io import echo, inputchoice, inputboolean
from bbsengine6.io.echo import echo_traceback
from bbsengine6.util import heading
from bbsengine6 import database
from bbsengine6.listbox import Listbox, ListboxItem

from . import address_domain, address


PGSQL_TEMPLATE = """# {domain_name} - Postfix PostgreSQL lookup
# Auto-generated by address_manager TUI
# DO NOT EDIT DIRECTLY

dbname = {dbname}
user = postfix
password = {password}
host = {host}
port = {port}

query = SELECT destination FROM mistermcfeely.address a
        JOIN mistermcfeely.address_domain d ON a.domain_id = d.id
        WHERE a.local_part = '%u' AND d.name = '{domain_name}' AND a.enabled = true AND d.enabled = true
"""


def _help() -> str:
    return "(d)omains, (a)ddresses, (s)ettings, (r)eload, (q)uit"


def _settings_help() -> str:
    return "(g)enerate postfix config, (p)ostfix config path, e(x)it"


def _select_domain(args: Any, pool: Any) -> dict | None:
    sql = "SELECT id, name, enabled FROM mistermcfeely.address_domain ORDER BY name"

    try:
        with database.connect(args, pool=pool) as conn:
            with conn.cursor() as cur:
                cur.execute(sql)
                rows = cur.fetchall()

                if not rows:
                    echo("No domains configured", level="error")
                    echo("Add one via (d)omains menu")
                    return None

                items = []
                for row in rows:
                    status = "[*]" if row["enabled"] else "[-]"
                    items.append(
                        ListboxItem(
                            content=f"{status} {row['name']}", pk=row["id"], data=row
                        )
                    )

                lb = Listbox(args, title="Select Domain", items=items, itemsperpage=20)
                result = lb.run("Select domain: ")

                if result.status == "selected" and result.item:
                    return result.item.data

    except Exception:
        echo_traceback("Error listing domains")

    return None


def _generate_postfix_config(args: Any, pool: Any, current_user: str) -> None:
    domain = _select_domain(args, pool)
    if not domain:
        return

    echo("")
    echo(f"Generating Postfix config for: {domain['name']}")

    config_path = f"/etc/postfix/{_sanitize_domain(domain['name'])}_pgsql.cf"

    try:
        dbname = getattr(args, "databasename", "postoffice")
        getattr(args, "databaseuser", "postfix")
        dbpass = getattr(args, "databasepassword", "")
        dbhost = getattr(args, "databasehost", "localhost")
        dbport = getattr(args, "databaseport", 5432)

        config_content = PGSQL_TEMPLATE.format(
            domain_name=domain["name"],
            dbname=dbname,
            password=dbpass or "CHANGEME",
            host=dbhost,
            port=dbport,
        )

        echo("")
        echo(f"Config would be written to: {config_path}")
        echo("")
        echo("Contents:")
        echo("---")
        echo(config_content)
        echo("---")

        confirm = inputboolean("Write to file? [Y/N]: ", default="Y")
        if not confirm:
            echo("Cancelled")
            return

        with open(config_path, "w") as f:
            f.write(config_content)

        echo(f"Written: {config_path}")
        echo("Run (r)eload postfix to apply changes")

    except PermissionError:
        echo(f"Permission denied: {config_path}", level="error")
        echo("Run as root or use sudo")
    except Exception:
        echo_traceback("Error writing config")


def _sanitize_domain(domain: str) -> str:
    return domain.replace(".", "_").replace("-", "_")


def _show_config_path() -> None:
    echo("")
    echo("Postfix pgsql config files are stored at:")
    echo("  /etc/postfix/{domain}_pgsql.cf")
    echo("")
    echo(
        "Example: projects.zoidtechnologies.com -> /etc/postfix/projects_zoidtechnologies_com_pgsql.cf"
    )
    echo("")
    echo("To use, add to main.cf virtual_alias_maps:")
    echo(
        "  virtual_alias_maps = pgsql:/etc/postfix/projects_zoidtechnologies_com_pgsql.cf ..."
    )


def _reload_postfix() -> None:
    echo("")
    echo("Reloading Postfix...")

    try:
        result = subprocess.run(
            ["systemctl", "reload", "postfix"],
            capture_output=True,
            text=True,
            timeout=30,
        )

        if result.returncode == 0:
            echo("Postfix reloaded successfully")
        else:
            echo(f"Failed to reload Postfix: {result.stderr}", level="error")

    except subprocess.TimeoutExpired:
        echo("Timeout reloading Postfix", level="error")
    except PermissionError:
        echo("Permission denied - run as root or use sudo", level="error")
    except Exception:
        echo_traceback("Error reloading Postfix")


def _settings(args: Any, pool: Any, current_user: str) -> None:
    echo("")
    heading("Settings")

    choice = inputchoice(
        "Choose action: ",
        "gpxq",
        default="g",
        help=_settings_help,
    )

    if choice == "G":
        _generate_postfix_config(args, pool, current_user)
    elif choice == "P":
        _show_config_path()
    elif choice == "X":
        return


def run(args: Any, moniker: str, pool: Optional[Any] = None, **kwargs) -> int:
    """Main address manager TUI loop."""
    should_close_pool = False

    if pool is None:
        try:
            pool = database.getpool(args)
            should_close_pool = True
        except Exception as e:
            echo(f"Error: Could not connect to database: {e}", level="error")
            return 1

    try:
        current_user = getattr(args, "loginid", "system")

        while True:
            echo("")
            heading("Address Manager")
            echo("Manage email addresses for domains")
            echo("")

            choice = inputchoice(
                "Choose action: ",
                "dasrq",
                default="d",
                help=_help,
            )

            if choice in ("Q",):
                echo("Goodbye!")
                return 0
            elif choice == "D":
                address_domain.run(args, moniker, pool=pool, **kwargs)
            elif choice == "A":
                domain = _select_domain(args, pool)
                if domain:
                    address.run(
                        args,
                        moniker,
                        pool=pool,
                        domain_id=domain["id"],
                        domain_name=domain["name"],
                        **kwargs,
                    )
            elif choice == "S":
                _settings(args, pool, current_user)
            elif choice == "R":
                _reload_postfix()

    finally:
        if should_close_pool:
            try:
                pool.closeall()
            except Exception:
                pass

    return 0
